{"path":"hesap.py","content":""""Küçük hesap dili yorumlayıcı.

`calistir(program: str)` bir program metnini yorumlar ve son ifadenin
değerini döndürür. `eval`, `exec`, `compile` ve `ast` KULLANILMAZ.
"""


# ---------------------------------------------------------------------------
# Sözlüksel (lexing) katman
# ---------------------------------------------------------------------------

_NUM_RE = None  # placeholder; regex yerine elle tarayıcı kullanıyoruz


def _tokenize(src: str):
    """Kaynak metni tokenlara ayırır.

    Tokenlar (tür, değer) çiftleri olarak üretilir:
      ("num", float|str)  -> sayı (float veya int-string; ayrıştırmada saklanır)
      ("name", str)       -> ad / fonksiyon adı
      ("op", str)         -> operatör: + - * / % ** ( ) , ;
    """
    tokens = []
    i, n = 0, len(src)
    while i < n:
        c = src[i]
        if c in " \t\r\n":
            i += 1
            continue
        # sayı: rakam ya da nokta ile başlayıp rakamlar/nokta içeren blok
        if c.isdigit() or (c == "." and i + 1 < n and src[i + 1].isdigit()):
            j = i
            seen_dot = False
            while j < n:
                cj = src[j]
                if cj.isdigit():
                    j += 1
                elif cj == "." and not seen_dot:
                    seen_dot = True
                    j += 1
                else:
                    break
            text = src[i:j]
            # "3." gibi tuhaf ama kabul edilen formu destekle
            if text.endswith("."):
                pass  # aynen sakla, parse aşamasında float yapılır
            tokens.append(("num", text))
            i = j
            continue
        # ad: harf ya da _ ile başlar, ardından harf/sayı/_
        if c.isalpha() or c == "_":
            j = i
            while j < n and (src[j].isalnum() or src[j] == "_"):
                j += 1
            tokens.append(("name", src[i:j]))
            i = j
            continue
        # iki karakterli operatör: **
        if c == "*" and i + 1 < n and src[i + 1] == "*":
            tokens.append(("op", "**"))
            i += 2
            continue
        if c in "+-*/%(),;":
            tokens.append(("op", c))
            i += 1
            continue
        raise SyntaxError(f"beklenmeyen karakter: {c!r}")
    return tokens


# ---------------------------------------------------------------------------
# Ayrıştırma (parsing) — Python öncelik sırasına göre rekürsif iniş indirimi
# ---------------------------------------------------------------------------

# Gramer (düşükten yükseğe):
#   statement  := assignment | expr
#   assignment := NAME '=' stmt   (sadece en üst düzeyde; solda ad olmalı)
#   expr       := ternary... yok -> additive
#   additive   := multiplicative (('+'|'-') multiplicative)*
#   multiplicative := unary (('*'|'/'|'%') unary)*
#   unary    := ('-'|'+')* power
#   power    := atom ('**' unary)?     # ** sağdan birleşir, üst tarafında unary olur
#   atom     := NUMBER | NAME ['(' args ')'] | '(' expr ')'

class _Parser:
    def __init__(self, tokens):
        self.toks = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.toks):
            return self.toks[self.pos]
        return (None, None)

    def next(self):
        tok = self.peek()
        self.pos += 1
        return tok

    def expect_op(self, op):
        kind, val = self.peek()
        if kind != "op" or val != op:
            raise SyntaxError(f"{op!r} bekleniyor")
        self.pos += 1

    # ---- ifadeler ---------------------------------------------------------

    def parse_expr(self, allow_assign=True):
        """En üst ifade (atama dahil). Atama soldaki ad + '=' ile oluşur."""
        kind, val = self.peek()
        if (
            allow_assign
            and kind == "name"
            and self.pos + 1 < len(self.toks)
            and self.toks[self.pos + 1] == ("op", "=")
        ):
            name = self.next()[1]
            self.expect_op("=")
            value = self.parse_expr(allow_assign=False)
            return ("assign", name, value)
        return self.parse_additive()

    def parse_additive(self):
        node = self.parse_multiplicative()
        while True:
            kind, val = self.peek()
            if kind == "op" and val in ("+", "-"):
                self.next()
                rhs = self.parse_multiplicative()
                node = ("bin", val, node, rhs)
            else:
                break
        return node

    def parse_multiplicative(self):
        node = self.parse_unary()
        while True:
            kind, val = self.peek()
            if kind == "op" and val in ("*", "/", "%"):
                self.next()
                rhs = self.parse_unary()
                node = ("bin", val, node, rhs)
            else:
                break
        return node

    def parse_unary(self):
        kind, val = self.peek()
        if kind == "op" and val in ("+", "-"):
            self.next()
            operand = self.parse_unary()  # tekli operatörler soldan birleşir
            return ("unary", val, operand)
        return self.parse_power()

    def parse_power(self):
        base = self.parse_atom()
        kind, val = self.peek()
        if kind == "op" and val == "**":
            self.next()
            # üst tarafında unary (tekli +/-) izlenebilir -> -2**2 ve 2**-1
            exponent = self.parse_unary()
            return ("bin", "**", base, exponent)
        return base

    def parse_atom(self):
        kind, val = self.peek()
        if kind == "num":
            self.next()
            node = ("number", _make_number(val))
            # sayıdan sonra beklenmeyen ikinci atom yakalanmasın (örn. "3 4")
            return node
        if kind == "name":
            self.next()
            k2, v2 = self.peek()
            if k2 == "op" and v2 == "(":
                self.next()
                args = []
                k3, v3 = self.peek()
                if not (k3 == "op" and v3 == ")"):
                    while True:
                        args.append(self.parse_expr(allow_assign=False))
                        k4, v4 = self.peek()
                        if k4 == "op" and v4 == ",":
                            self.next()
                            continue
                        break
                self.expect_op(")")
                return ("call", val, args)
            return ("name", val)
        if kind == "op" and val == "(":
            self.next()
            node = self.parse_expr(allow_assign=False)
            self.expect_op(")")
            return node
        raise SyntaxError(f"söz dizimi hatası: {kind} {val!r}")


def _make_number(text):
    if "." in text:
        return float(text)
    try:
        return int(text)
    except ValueError:
        return float(text)


# ---------------------------------------------------------------------------
# Değerlendirme (evaluation) katmanı — AST yerine düz Python tuple'ları kullanılır
# ---------------------------------------------------------------------------

_BUILTINS = {
    "min": min,
    "max": max,
    "abs": abs,
}


def _eval(node, env):
    tag = node[0]
    if tag == "number":
        return node[1]
    if tag == "name":
        name = node[1]
        if name not in env:
            raise NameError(f"tanımsız değişken: {name!r}")
        return env[name]
    if tag == "assign":
        _, name, value_node = node
        value = _eval(value_node, env)
        env[name] = value
        return value
    if tag == "unary":
        op, operand = node[1], node[2]
        v = _eval(operand, env)
        return -v if op == "-" else +v
    if tag == "bin":
        op, ln, rn = node[1], node[2], node[3]
        l = _eval(ln, env)
        r = _eval(rn, env)
        try:
            if op == "+":
                return l + r
            if op == "-":
                return l - r
            if op == "*":
                return l * r
            if op == "/":
                return l / r  # her zaman float; sıfırda ZeroDivisionError
            if op == "%":
                return l % r
            if op == "**":
                return l ** r
        except ZeroDivisionError:
            raise
        raise SyntaxError(f"bilinmeyen işleç: {op}")  # asla buraya gelmez
    if tag == "call":
        fname = node[1]
        fn = _BUILTINS.get(fname)
        if fn is None:
            raise NameError(f"bilinmeyen fonksiyon: {fname!r}")
        args = [_eval(a, env) for a in node[2]]
        return fn(*args)
    raise SyntaxError("geçersiz ifade düğümü")


# ---------------------------------------------------------------------------
# Dış API
# ---------------------------------------------------------------------------

def calistir(program: str):
    """Programı yorumlar; son ifadenin değerini döndürür."""
    # 1) her satırı ayrı ayrı işle (boşluk/satır sonu ve `;` ayracı aynı katmanda)
    env = {}
    last = None
    for line in program.splitlines():
        # yorum (#) satırın kalanını siler — tırnak içermeyen dilde güvenli
        hash_idx = line.find("#")
        if hash_idx != -1:
            line = line[:hash_idx]
        chunks = [c.strip() for c in line.split(";")]
        for chunk in chunks:
            if not chunk:
                continue
            tokens = _tokenize(chunk)
            parser = _Parser(tokens)
            node = parser.parse_expr(allow_assign=True)
            # ifade bitti, token kalmamalı (örn. "2 + 3 4")
            if parser.pos != len(parser.toks):
                kind, val = parser.peek()
                raise SyntaxError(f"söz dizimi hatası: {val!r}")
            last = _eval(node, env)
    return last
